    {
      "section": "V1",
      "lyrics": [
        "“普通”とか“あたりまえ”ってなんだろう",
        "今 手にある物差しでは",
        "全然上手く測れなくって",
        "吐いては また吸い込んだ不安に",
        "僕は為すがまま立ち尽くして"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "不器用で 空回って",
        "傷つくことから逃げている",
        "現実とノートで行ったり来たり 慰めて",
        "あぁ",
        "なんて生きづらい世界なんだろう",
        "だけど だけど"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "ぜんぶ ぜんぶ 僕だから",
        "うじうじ しくしく 僕だから",
        "ぜんぶ ぜんぶ 抱きしめて",
        "少し眠ろう",
        "痛いの痛いの飛んでゆけ",
        "悲しみにすべてを奪われないように",
        "僕は 僕の味方でいようよ",
        "まだまだ長い道の途中",
        "ちょっとくらい休憩したって",
        "誰にも叱られはしないから"
      ]
    }
  ],
