      "phrases": [
        {
          "id": "C1-01",
          "zh": "全部 全部 都是我"
        },
        {
          "id": "C1-02",
          "zh": "闷闷 泣泣 也是我"
        },
        {
          "id": "C1-03",
          "zh": "全部 全部 抱紧吧"
        },
