        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "全部 全部 都是我模样"
        },
        {
          "id": "C1-02",
          "zh": "黏黏糊糊 抽抽搭搭 也全都是我"
        },
        {
          "id": "C1-03",
          "zh": "全部 全部 都抱进怀里"
        },
        {
          "id": "C1-04",
          "zh": "闭上眼 睡一会"
        },
        {
          "id": "C1-05",
          "zh": "痛痛飞吧 痛痛飞吧 飞远一点"
        },
        {
          "id": "C1-06",
          "zh": "别让悲伤把我的一切全都夺走 才好"
        },
        {
          "id": "C1-07",
          "zh": "我要做我自己 最靠得住的同伴"
        },
        {
          "id": "C1-08",
          "zh": "路还很长 我才刚走到一半呢"
        },
        {
          "id": "C1-09",
          "zh": "坐一小会 也不算偷懒"
        },
        {
          "id": "C1-10",
          "zh": "没有人会 皱起眉头来 数落你半句"
        }
      ]
    }
